  // Batch prep: [Sunday job, what's left on the day]. Mon–Sat meals are cooked on Sunday where it works.
  const PREP = {
    "l-salmon-poke": ["Per portion: season the salmon with ½ tsp salt and 1 tsp soy, roast at 200°C for 12 min, then flake. Slice the cucumber into half-moons and toss with a pinch of salt and 1 tsp rice vinegar. Sauce pot: 10 g light mayo, 10 g sriracha, 10 ml soy, ½ tsp sesame oil. Box with the edamame", "Microwave the rice until steaming, top with the cold salmon and veg, add sauce. 3 min"],
    "l-tuna-poke": ["Per portion: quick-pickle the cucumber (1 tsp rice vinegar, pinch of salt and sugar). Box rice with edamame and cucumber. Tuna pot: drained tuna mixed with 15 g light mayo, 10 g sriracha, 10 ml soy and a squeeze of lime. Make Thursday's tuna on Wednesday night", "Microwave the rice until steaming, top with tuna and veg. 3 min"],
    "l-teriyaki": ["Per portion: marinate the thighs 30 min in 15 ml teriyaki, 5 ml soy, 1 grated garlic clove and 1 tsp grated ginger. Air-fry at 200°C for 18 min, brushing with another 15 ml teriyaki for the last 5. Slice. Steam the greens 3 min, toss in a few drops of sesame oil and a pinch of salt. Box with rice, furikake in a twist of foil", "Microwave until steaming throughout. 3 min"],
    "l-bulgogi": ["For all portions: brown the mince hard in a dry pan in batches. Per portion add 1 grated garlic clove, 1 tsp grated ginger, 20 g gochujang, 15 ml soy and 5 g honey; cook down until sticky, finish with 5 ml sesame oil and sliced spring onion. Box with rice; kimchi in a separate pot", "Microwave until steaming, kimchi on top. 3 min"],
    "l-prawn-egg": ["Boil the eggs 7 min, into iced water, peel. Per portion: toss the prawns in 10 ml soy, ½ tsp sesame oil and a pinch of chilli flakes; mix 10 g light mayo with 1 tsp sriracha in a pot. Box rice with edamame; eggs and prawns in a separate tub", "Microwave the rice until steaming, add the cold prawns, halved eggs, mayo and furikake. 2 min"],
    "l-shawarma": ["Per portion marinade: 30 g Greek yoghurt, 1 tsp each cumin and smoked paprika, ½ tsp each turmeric, cinnamon and garlic granules, juice of ¼ lemon, ½ tsp salt, 5 ml olive oil. Marinate the thighs 1 hour (or overnight), roast at 220°C for 20 min, rest and slice. Tahini sauce: 30 g yoghurt, 8 g tahini, squeeze of lemon, pinch of salt. Chop cucumber and tomato with parsley; pickles in the salad pot", "Microwave chicken and rice until steaming, add the cold salad and sauce. 3 min"],
    "l-spicy-salmon": ["Per portion: season the salmon with salt and pepper, roast at 200°C for 12 min, flake and mix with 15 g light mayo, 15 g sriracha and 5 ml soy. Season the rice with the sushi vinegar. Box with sliced cucumber and edamame, furikake on top", "Microwave the rice until steaming, top with the salmon mix. 2 min"],
    "l-onigiri": ["Sunday lunch: make fresh. Season the rice with sushi vinegar; fill with tuna mixed with light mayo and a little soy; shape with wet, salted hands; roll the edges in furikake", "Eat cold. 0 min"],
    "l-thai-beef-salad": ["Per portion: rub the steak with ½ tsp salt and pepper, sear 2 min a side in a ripping-hot pan, rest 5 min, slice thin. Soak the noodles in boiling water 5 min, rinse cold, toss in a few drops of oil. Dressing jar per portion: juice of ½ lime, 15 ml fish sauce, 5 g honey, ½ chopped red chilli, ½ grated garlic clove. Slice the cucumber, tomato and red onion; pick the mint and coriander. Peanuts crushed in a separate bag", "Toss everything with the dressing, peanuts on top. 2 min"],
    "l-caesar": ["Per portion: rub the chicken with 5 ml olive oil, ½ tsp garlic granules, ½ tsp dried oregano, salt, pepper and lemon zest; grill or air-fry at 200°C for 15–18 min to 74°C inside; rest and slice. Croutons: cube the sourdough, spray with oil, pinch of salt and garlic granules, bake at 200°C for 8 min. Dressing jar: 50 g Greek yoghurt, 10 g light mayo, 1 grated garlic clove, 1 tsp Dijon, juice of ¼ lemon, a few drops of Worcestershire, 1 tbsp grated parmesan, black pepper. Wash, dry and chop the cos", "Toss lettuce, chicken and dressing, croutons and the rest of the parmesan on top. 2 min"],
    "l-satay-noodle": ["Per portion: poach the chicken in simmering water with a slice of ginger for 12 min, cool and shred. Noodles: soak 5 min, rinse cold, toss in a little oil. Satay sauce jar per portion: 20 g peanut butter, 15 ml soy, juice of ⅓ lime, 5 g honey, 5 g sriracha, ½ grated garlic clove, loosened with 2–3 tbsp hot water. Julienne the cucumber and peppers; keep the beansprouts separate", "Toss everything with the sauce, cold. Coriander if you have it. 2 min"],
    "l-prawn-mango": ["Dice the mango and cucumber and shred the lettuce. Dressing jar per portion: juice of ⅓ lime, 10 g sriracha, 5 g honey, pinch of salt, chopped coriander. Box the rice; prawns in a separate tub. Keep the avocado whole until the day", "Microwave the rice until steaming, add prawns, mango, avocado and dressing. 3 min"],
    "l-spicy-tuna-salad": ["Season the rice with the sushi vinegar and box with edamame, sliced cucumber and shredded lettuce. Sauce pot per portion: 15 g light mayo, 15 g sriracha, a squeeze of lime", "Mix the tuna with the sauce, build over the leaves and warm rice, furikake on top. 3 min"],

    "d-ragu": ["For all portions: season the shin with salt and pepper and brown hard in batches. Per portion soften 60 g diced onion, plus carrot and celery if you have them, with 1 garlic clove and a sprig of rosemary; add 1 tsp tomato purée, 200 g passata, 100 ml beef stock, a bay leaf and ½ tsp dried oregano. Cover and cook low (150°C oven) for 3 hours, or 50 min in a pressure cooker. Shred, reduce until thick, season, portion", "Reheat the ragù until piping hot, toss with the pasta, a splash of water and parmesan. 6 min"],
    "d-chicken-parm": ["Per portion: butterfly and bash the breast to 1.5 cm; season with salt, pepper and garlic granules; dip in beaten egg then panko mixed with 1 tsp dried oregano and 1 tbsp grated parmesan. Freeze raw on a lined tray, then bag. Marinara: 120 g passata simmered 10 min with ½ garlic clove, ½ tsp oregano, a pinch of chilli, salt and a few torn basil leaves; portion", "Air-fry the chicken from frozen at 200°C for 18 min, sauce and mozzarella on for 3 min; reheat the pasta in the rest of the sauce. 20 min hands-off"],
    "d-gyros": ["Per portion marinade: 30 g Greek yoghurt, juice of ¼ lemon, 1 grated garlic clove, 1 tsp dried oregano, 1 tsp smoked paprika, ½ tsp cumin, ½ tsp salt, 5 ml olive oil. Marinate the thighs 1 hour, grill or air-fry at 200°C for 18 min, slice and portion. Tzatziki: 30 g yoghurt, 30 g grated and squeezed cucumber, ½ garlic clove, a few mint leaves, salt. Slice the red onion and tomato", "Air-fry the chips 15 min; warm the chicken; build the wrap with tzatziki, salad and a few chips. 15 min"],
    "d-honey-garlic": ["Per portion: season the diced thighs with salt and pepper and sear until golden. Sauce: 20 g honey, 20 ml soy, 2 grated garlic cloves, 1 tsp rice vinegar and a pinch of chilli flakes; reduce over the chicken to a sticky glaze. Char the broccoli in a hot pan with a pinch of salt. Box with rice, sesame seeds and spring onion on top", "Microwave until steaming. 4 min"],
    "d-smash": ["Per portion: weigh 2 × 90 g balls of mince (don't season yet), freeze between squares of baking paper. Burger sauce pot: 10 g light mayo, 10 g ketchup, 1 tsp American mustard, 1 tsp chopped gherkin plus a splash of its brine, pinch of smoked paprika. Slice the onion very thin", "Air-fry the chips 15 min. Smash each ball on a ripping-hot dry pan, season with salt and pepper, 2 min, flip, cheese on, 1 min. Build in a toasted bun. 15 min"],
    "d-crispy-burger": ["Per portion: butterfly the breast; season with ½ tsp smoked paprika, ½ tsp garlic granules, ¼ tsp cayenne, salt and pepper; dip in beaten egg, then panko seasoned the same way. Freeze raw on a lined tray, then bag. Sriracha mayo pot: 15 g light mayo, 5 g sriracha, squeeze of lime", "Air-fry chicken and chips together at 200°C for 18 min; bun, lettuce and sriracha mayo. 20 min hands-off"],
    "d-philly": ["Freeze the steak 20 min, slice paper-thin and freeze flat in portion bags. Per portion: slice 60 g onion and 60 g peppers and cook slowly in a little oil with a pinch of salt for 15 min until soft and sweet; season with black pepper and a few drops of Worcestershire; portion", "Flash-fry the steak 2 min with the veg, season, lay the cheese over to melt, pile into the toasted roll. Air-fry the chips. 15 min"],
    "d-bbq-chicken": ["Per portion: rub the thighs with 1 tsp smoked paprika, ½ tsp garlic granules, ½ tsp onion powder, salt and pepper. Pressure-cook 12 min, or poach covered 25 min, in 100 ml stock. Shred and toss with 30 g BBQ sauce and a splash of the cooking liquid. Slaw: shred 80 g cabbage (plus carrot); dressing pot of 15 g light mayo, 1 tsp cider vinegar, pinch of salt", "Reheat the chicken until steaming; air-fry the chips; dress the slaw; build. 15 min"],
    "d-fried-rice": ["Cook the rice for this the day before if you can (Saturday) and chill it. Per portion: wok the diced chicken hard with salt and white pepper, push aside and scramble 2 eggs; add the cold rice, 60 g peas and chopped spring onion; season with 20 ml soy and 7 ml sesame oil. Cool fast and portion", "Microwave or stir-fry until piping hot. 4 min"],
    "d-beef-broccoli": ["Per portion: slice the steak thin and toss in 4 g cornflour, ½ tsp soy and a pinch of salt; sear in batches in a very hot wok. Blanch the broccoli 2 min. Sauce: 20 ml soy, 10 g honey, 1 grated garlic clove, 1 tsp grated ginger, 4 g cornflour and 60 ml water, simmered until glossy; toss everything together. Portion with rice", "Microwave until steaming. 4 min"],
    "d-salt-pepper": ["Per portion: dice the chicken and toss in 20 g cornflour seasoned with ½ tsp salt, ½ tsp black pepper and ¼ tsp Chinese five-spice; spray with oil and air-fry at 200°C for 12 min. Wok the sliced onion and peppers with 1 garlic clove and ½ red chilli. Mix a seasoning pot: ½ tsp salt, ½ tsp pepper, ¼ tsp five-spice, pinch of sugar. Portion the chicken, veg and rice separately", "Air-fry the chicken 5 min to re-crisp, toss with the veg and the seasoning; microwave the rice. 8 min"],
    "d-sweet-sour": ["Per portion: dice and cornflour-coat the chicken as for salt and pepper; air-fry at 200°C for 12 min. Sauce: 25 g ketchup, 10 g honey, 15 ml rice vinegar, 10 ml soy, 50 ml pineapple juice from the tin, 3 g cornflour; simmer until glossy. Wok the peppers and onion, add the pineapple and sauce, toss the chicken through. Portion with rice", "Microwave until steaming. 4 min"],
    "d-doner": ["Per portion: blitz the mince to a smooth paste with ½ tsp salt, ½ tsp cumin, ½ tsp ground coriander, ½ tsp dried oregano, ½ tsp smoked paprika, ¼ tsp chilli flakes, ½ tsp garlic granules and ½ tsp onion powder. Pack into a tight loaf, wrap in foil and bake at 180°C for 50 min, then 10 min uncovered. Chill, slice paper-thin, portion. Garlic sauce: 50 g Greek yoghurt, 1 grated garlic clove, squeeze of lemon, pinch of salt and dried mint. Slice the onion and tomato", "Crisp the doner slices in a hot dry pan 3 min; air-fry the chips; wrap with salad, garlic sauce and chilli sauce. 15 min"],
    "d-shish": ["Per portion marinade: 40 g Greek yoghurt, 1 tsp smoked paprika, ½ tsp cumin, ½ tsp chilli flakes, 1 grated garlic clove, juice of ¼ lemon, 1 tsp tomato purée, ½ tsp salt. Marinate the cubed chicken at least 2 hours, skewer and grill or air-fry at 220°C for 14 min; portion. Garlic sauce as for the doner", "Warm the chicken; air-fry the chips; wrap with salad and garlic sauce. 15 min"],
    "d-kofta": ["Per portion: mix the mince with 30 g grated and squeezed onion, 1 grated garlic clove, ½ tsp each cumin, ground coriander and smoked paprika, ¼ tsp cinnamon, ½ tsp salt and a handful of chopped parsley. Shape onto skewers and grill hard 8–10 min. Tahini yoghurt: 50 g yoghurt, 10 g tahini, lemon, salt. Chop cucumber and tomato with parsley. Portion with rice", "Microwave the koftas and rice until steaming, add salad and sauce. 5 min"],
    "d-kebab-fries": ["Per portion: marinate the thighs in 20 g yoghurt, 1 tsp smoked paprika, ½ tsp cumin, ½ tsp garlic granules, ¼ tsp chilli flakes and ½ tsp salt; grill or air-fry at 200°C for 18 min, slice. Garlic sauce: 60 g yoghurt, 1 grated garlic clove, lemon, salt, dried mint. Slice the onion and shred the lettuce", "Air-fry the chips 15 min, add the chicken and cheese for 3 min, top with sauce, chilli sauce, onion and lettuce. 18 min"],
    "d-bigmac": ["Per portion: brown the mince hard with 30 g finely diced onion, ½ tsp salt, ½ tsp black pepper, ½ tsp garlic granules and a dash of Worcestershire; portion. Big Mac sauce pot: 20 g light mayo, 10 g ketchup, 1 tsp American mustard, 1 tsp finely chopped gherkin plus a splash of brine, ¼ tsp smoked paprika, ¼ tsp onion powder. Shred the lettuce", "Air-fry the potatoes 15 min, reheat the mince until steaming, build the bowl with cheese, gherkins and sauce. 15 min"],
    "d-pizza": ["Per portion: season the chicken with ½ tsp dried oregano, ½ tsp garlic granules, salt and pepper, grill and slice. Pizza sauce pot: 60 g passata, ½ tsp dried oregano, ½ grated garlic clove, pinch of salt, sugar and chilli flakes", "Spread the sauce thin, top and bake on a hot tray at the oven's hottest for 8–10 min. 12 min"],
    "d-meatball-sub": ["Per portion: mix the mince with 15 g panko, 15 g beaten egg, 1 grated garlic clove, 10 g grated parmesan, ½ tsp dried oregano, ½ tsp salt and black pepper; roll 6 meatballs and brown. Simmer 12 min in 120 g passata with ½ garlic clove, ½ tsp oregano, a pinch of chilli flakes and torn basil. Portion", "Reheat until piping hot, fill the toasted roll, mozzarella on top, grill to melt. 8 min"],
    "d-quesadilla": ["Per portion: slice the chicken and toss in 1 tsp smoked paprika, ½ tsp cumin, ½ tsp garlic granules, ½ tsp chilli powder, ¼ tsp oregano, salt and a squeeze of lime; cook hot with the sliced peppers and onion. Cool and portion. Salsa and yoghurt in separate pots", "Fill the wraps with the cold filling and cheese; dry-fry 2 min a side. 6 min"],
    "d-carbonara": ["Per portion: dice the bacon medallions and crisp in a dry pan. Season the chicken with salt and pepper, pan-fry and slice. Box the meat together. Grate the pecorino into a separate pot", "Cook the spaghetti; whisk 2 eggs, 1 yolk, the pecorino and plenty of black pepper; off the heat toss pasta, meat, egg mix and a splash of pasta water until glossy. 12 min, best fresh"],
    "d-lasagne": ["Ragù per portion: brown the mince with 50 g onion and 1 garlic clove, add 150 g passata, 1 tsp tomato purée, ½ tsp oregano, a bay leaf, salt and pepper; simmer 30 min. White sauce per portion: 150 ml skimmed milk thickened with 12 g cornflour, a pinch of nutmeg, salt, pepper and half the parmesan. Layer ragù, sheets and white sauce; top with mozzarella and the rest of the parmesan; bake at 190°C for 40 min. Rest 15 min, cut, portion", "Microwave until piping hot. 5 min"],
    "d-prawn-linguine": ["Arrabbiata per portion: 10 ml olive oil, 2 sliced garlic cloves and ½ tsp chilli flakes warmed gently, then 200 g chopped tomatoes, a pinch of sugar and salt; simmer 15 min until thick. Portion", "Cook the linguine 9 min, reheat the sauce, prawns in for 2 min, toss with pasta water, parsley and parmesan. 12 min"],
    "d-steak-chips": ["Nothing to cook. Steak is best fresh. Take it out of the fridge 30 min before cooking", "Air-fry the chips 15 min; season the steak with salt and pepper, sear 2–3 min a side with a knob of butter, garlic and thyme for the last minute; rest 5 min. 15 min"],
    "d-roast-chicken": ["Sunday dinner: cook fresh", "Season the chicken with salt, pepper, garlic, thyme and lemon; roast to 74°C inside. About an hour"],
    "d-roast-beef": ["Sunday dinner: cook fresh", "Rub the topside with salt, pepper, mustard and rosemary; sear, roast at 180°C to 52°C inside; rest 20 min. About 1½ hours"],
    "d-roast-pork": ["Sunday dinner: cook fresh", "Score the fat, rub with salt and fennel seeds, roast to 63°C inside; rest. About 1½ hours"],
    "d-pasta-bake": ["Per portion: brown the diced chicken and bacon with salt and pepper; add 1 garlic clove, 150 g passata, ½ tsp dried oregano, a pinch of chilli flakes and torn basil; simmer 10 min. Stir through the penne (cooked 2 min short), top with mozzarella and parmesan, bake at 200°C for 15 min. Portion", "Microwave until piping hot. 5 min"],
    "d-thai-green-curry": ["Per portion: fry 30 g green curry paste in a little oil for 1 min; add the sliced thighs and seal; pour in 150 ml light coconut milk and 50 ml water; simmer 10 min with the peppers and broccoli; season with 10 ml fish sauce, juice of ¼ lime, a pinch of sugar and a handful of Thai basil. Portion with rice", "Microwave until steaming. 5 min"],
    "d-tikka": ["Per portion marinade: 40 g Greek yoghurt, half the curry paste (about 12 g), 1 grated garlic clove, juice of ¼ lemon, ½ tsp salt. Marinate the cubed chicken 1 hour, then grill or air-fry at 220°C for 12 min. Sauce: soften 50 g onion with 1 garlic clove and 1 tsp grated ginger, fry the rest of the paste 1 min, add 120 g passata and 60 ml light coconut milk; simmer 10 min, blend smooth, add the chicken and ½ tsp garam masala. Portion with rice", "Microwave until steaming, coriander on top. 5 min"],
    "d-jalfrezi": ["Per portion: char 80 g chunky onion and 100 g peppers in a hot pan with half the oil; set aside. Fry the curry paste 1 min with 1 garlic clove, 1 tsp ginger and 1 sliced green chilli; brown the chicken; add 150 g chopped tomatoes and ½ tsp salt; simmer 12 min; return the veg with ½ tsp garam masala and a squeeze of lemon. Portion with rice", "Microwave until steaming, coriander on top. 5 min"],
    "d-katsu-curry": ["Per portion: flatten the breast, season with salt and pepper, dip in egg then panko; freeze raw on a lined tray, then bag. Katsu sauce: soften 50 g onion (plus a small carrot) with 1 garlic clove and 1 tsp ginger, add 20 g curry paste and 1 tsp honey, then 80 ml light coconut milk and 100 ml water; simmer 10 min and blend smooth. Portion the sauce and rice", "Air-fry the chicken from frozen at 200°C for 18 min; reheat the sauce and rice. 20 min hands-off"],
    "d-pad-thai": ["Per portion: season and pan-fry the chicken, slice. Sauce jar: 10 ml fish sauce, 15 ml soy, 10 g honey, juice of ⅓ lime, 1 tsp rice vinegar, ¼ tsp chilli flakes (or 1 tsp tamarind paste if you have it). Slice the onion and spring onion; crush the peanuts; keep the beansprouts in their bag", "Soak the noodles 5 min; wok the prawns 2 min, push aside and scramble the egg; add noodles, chicken and sauce, toss with beansprouts; peanuts and lime on top. 10 min, best fresh"],
    "d-thai-basil": ["Per portion: pound 2 garlic cloves with 1–2 bird's-eye chillies; fry in a hot wok 30 s; add the mince and brown hard; add the sliced peppers, 15 ml soy, 10 ml fish sauce, 5 g honey and 1 tsp oyster sauce if you have it; cook until sticky, then stir in a big handful of basil. Portion with rice", "Microwave until steaming; fry an egg in a hot pan until the edges crisp and put it on top. 5 min"],
    "d-peri-peri": ["Per portion: marinate the thighs in 30 g peri-peri sauce, juice of ¼ lemon, 1 grated garlic clove and ½ tsp smoked paprika, at least 1 hour. Grill or air-fry at 200°C for 18 min. Spicy rice: cook the rice with ½ tsp smoked paprika, ¼ tsp turmeric, ½ tsp garlic granules, the diced peppers and ½ stock cube. Garlic dip: 40 g yoghurt, ½ garlic clove, lemon, salt. Portion", "Microwave until steaming; corn on the side. 5 min"],
    "d-burrito-bowl": ["Per portion: rub the chicken with 1 tsp smoked paprika, ½ tsp cumin, ½ tsp chipotle or chilli powder, ½ tsp garlic granules, ¼ tsp oregano, salt and a squeeze of lime; grill and slice. Lime rice: stir the zest and juice of ¼ lime and chopped coriander through the rice. Beans and corn: warm with a pinch of cumin and salt. Salsa and yoghurt in pots", "Microwave the chicken, rice and beans until steaming, add the cold toppings and cheese. 4 min"],
    "d-chilli": ["Per portion: brown the mince hard; add 60 g onion, 60 g peppers and 1 garlic clove; stir in 1 tsp cumin, 1 tsp smoked paprika, ½ tsp chilli powder, ½ tsp dried oregano, ¼ tsp cinnamon and 1 tsp tomato purée; add 200 g chopped tomatoes, 100 ml beef stock and the beans; simmer 30 min. A square of dark chocolate at the end deepens it. Season, portion with rice", "Microwave until steaming, yoghurt on top. 5 min"],
    "d-massaman": ["Per portion: brown the beef in batches; fry 25 g massaman (or curry) paste 1 min; add 120 ml light coconut milk, 150 ml water, 50 g onion, 5 ml fish sauce, 1 tsp honey, a cinnamon stick and a bay leaf; simmer low 1½ hours. Add the potato chunks for the last 30 min. Portion with rice; peanuts in a bag", "Microwave until steaming, peanuts on top. 5 min"],

    "s-choc-mousse": ["Per pot: whisk 250 g skyr, 30 g chocolate whey, 10 g cocoa and 10 g honey until thick and smooth; spoon into a jar, berries on top, grate over the dark chocolate. Makes up to Wednesday's; make the rest Wednesday night", "Grab a pot, a few berries on top. 1 min"],
    "s-brownie": ["Per 2 squares: blitz 30 g oats to flour; mix with 30 g chocolate whey, 12 g cocoa, ½ beaten egg, 15 g honey, a pinch of salt and baking powder and enough milk for a thick batter; fold in 10 g chopped dark chocolate. Bake the whole batch in a lined tin at 180°C for 15–18 min until just set. Cool, cut, bag (fridge 5 days or freeze)", "Two squares with Greek yoghurt and berries. 1 min"],
    "s-cheesecake": ["Per pot: crush a digestive into the jar; whisk 200 g skyr, 30 g light cream cheese, 30 g vanilla whey, 10 g honey and a few drops of vanilla until smooth; spoon over; top with berries. Keeps 3 days; make the rest Wednesday night", "Grab a pot. 0 min"],
    "s-bark": ["For the tray: mix the Greek yoghurt with the honey and a few drops of vanilla; spread 1 cm thick on a lined tray; scatter berries, granola and chopped dark chocolate; freeze 3 hours, snap into shards and bag", "Snap off a portion. 0 min"],
    "s-crumble": ["Crumble jar per portion: rub 30 g oats with 10 g peanut butter, 5 g honey and a pinch each of cinnamon and salt; bake at 180°C for 8–10 min until golden. Apple per portion: dice and cook with 5 g honey, ½ tsp cinnamon and a splash of water for 5 min; portion. Vanilla yoghurt: stir the whey into the Greek yoghurt; portion", "Layer apple, yoghurt and crumble. 2 min"],
    "sh-choc-pb": ["Made fresh each morning", "Blend with ice 30–40 s. 3 min"],
    "sh-strawberry": ["Made fresh each morning", "Blend with ice until smooth. 3 min"],
    "sh-mocha": ["Made fresh each morning", "Brew the coffee, blend with ice until frothy. 4 min"],
    "sh-lassi": ["Made fresh each morning", "Blend until smooth and thick. 3 min"],
    "sh-berry-oat": ["Made fresh each morning", "Blend 45 s so the oats go smooth. 3 min"],
    "s-pbj": ["Nothing to prep", "Spread 4 rice cakes with peanut butter and jam; yoghurt and berries on the side. 3 min"],
    "snack": ["Nothing to prep", "Yoghurt, honey, berries and granola; an apple. 2 min"]
  };

